CREATE TYPE "AssetStatus" AS ENUM ('PENDING_UPLOAD','UPLOADING','QUARANTINED','SCANNING','READY','REJECTED','DELETED');CREATE TYPE "Visibility" AS ENUM ('PRIVATE','TENANT','PUBLIC');
CREATE TABLE "Tenant"("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"storageQuotaBytes" BIGINT NOT NULL DEFAULT 5000000000);CREATE TABLE "ApiKey"("id" TEXT PRIMARY KEY,"tenantId" TEXT NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE,"name" TEXT NOT NULL,"keyHash" TEXT NOT NULL UNIQUE);CREATE INDEX "ApiKey_tenantId_idx" ON "ApiKey"("tenantId");
CREATE TABLE "Asset"("id" TEXT PRIMARY KEY,"tenantId" TEXT NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE,"fileName" TEXT NOT NULL,"mediaType" TEXT NOT NULL,"bytes" BIGINT NOT NULL,"checksum" TEXT NOT NULL,"status" "AssetStatus" NOT NULL DEFAULT 'PENDING_UPLOAD',"visibility" "Visibility" NOT NULL DEFAULT 'PRIVATE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE INDEX "Asset_tenantId_status_createdAt_idx" ON "Asset"("tenantId","status","createdAt");
CREATE TABLE "AssetVersion"("id" TEXT PRIMARY KEY,"assetId" TEXT NOT NULL REFERENCES "Asset"("id") ON DELETE CASCADE,"version" INTEGER NOT NULL,"objectKey" TEXT NOT NULL,"scanVerdict" TEXT,"metadata" JSONB,UNIQUE("assetId","version"));CREATE TABLE "AuditEvent"("id" TEXT PRIMARY KEY,"tenantId" TEXT NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE,"actorId" TEXT NOT NULL,"action" TEXT NOT NULL,"assetId" TEXT NOT NULL,"correlationId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE INDEX "AuditEvent_tenantId_createdAt_idx" ON "AuditEvent"("tenantId","createdAt");

